<script setup lang="ts">
import {seoulDate} from '#shared/model'
import {summary,formatDuration,reviewed,scheduled} from '#domain/learning'
const {state}=useLearning(),today=seoulDate(),month=ref(today.slice(0,7)),selected=ref(today)
const cells=computed(()=>{const [y,m]=month.value.split('-').map(Number);const count=new Date(y!,m!,0).getDate(),offset=new Date(`${month.value}-01T12:00:00+09:00`).getUTCDay();return [...Array.from({length:offset},()=>null),...Array.from({length:count},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`)]})
const records=computed(()=>state.value.sessions.filter(s=>s.date===selected.value).sort((a,b)=>b.startedAt.localeCompare(a.startedAt)))
const period=ref<'week'|'month'>('month')
const periodSessions=computed(()=>{const start=new Date(`${today}T12:00:00+09:00`);start.setUTCDate(start.getUTCDate()-((start.getUTCDay()+6)%7));const end=new Date(start);end.setUTCDate(end.getUTCDate()+6);return state.value.sessions.filter(s=>s.status==='completed'&&(period.value==='month'?s.date.startsWith(month.value):s.date>=seoulDate(start)&&s.date<=seoulDate(end)))})
const attempts=computed(()=>periodSessions.value.flatMap(s=>s.attempts))
function status(date:string){const s=state.value.sessions.filter(s=>s.date===date);if(s.some(s=>s.status==='completed'))return '완료';if(s.length)return '진행 중';if(!scheduled(state.value.plan,date))return '휴식일';return date<today?'미완료':'예정'}
function changeMonth(delta:number){const [y,m]=month.value.split('-').map(Number);const d=new Date(Date.UTC(y!,m!-1+delta,1));month.value=d.toISOString().slice(0,7);selected.value=`${month.value}-01`}
</script>
<template><div class="page history-page"><div class="eyebrow">MY LEARNING JOURNAL</div><h1>쌓여가는 학습 기록</h1><p class="page-intro">얼마나 빨리 풀었는지보다, 무엇을 배웠는지 살펴봐요.</p><div class="section-heading"><h2>{{period==='month'?'선택한 달':'이번 주'}}의 연습</h2><div class="segmented compact"><button :class="{active:period==='week'}" @click="period='week'">주간</button><button :class="{active:period==='month'}" @click="period='month'">월간</button></div></div><div class="history-stats"><div><span>학습한 날</span><b>{{new Set(periodSessions.map(s=>s.date)).size}}<small>일</small></b></div><div><span>푼 문제</span><b>{{attempts.length}}<small>문제</small></b></div><div><span>정답률</span><b>{{attempts.length?Math.round(attempts.filter(a=>a.correct).length/attempts.length*100)+'%':'—'}}</b></div><div><span>학습 시간</span><b class="duration-value">{{formatDuration(attempts.reduce((a,b)=>a+b.durationMs,0))}}</b></div></div><div class="history-columns"><section class="calendar-panel"><div class="section-heading"><h2>{{month.replace('-','년 ')}}월</h2><div class="calendar-controls"><button aria-label="이전 달" @click="changeMonth(-1)">‹</button><button aria-label="다음 달" @click="changeMonth(1)">›</button></div></div><div class="calendar-grid"><span v-for="day in ['일','월','화','수','목','금','토']" :key="day" class="calendar-weekday">{{day}}</span><template v-for="(date,i) in cells" :key="i"><button v-if="date" :class="{selected:date===selected,today:date===today,done:status(date)==='완료'}" :aria-label="`${date} ${status(date)}`" :aria-pressed="date===selected" @click="selected=date"><b>{{Number(date.slice(-2))}}</b><small>{{status(date)==='미완료'?'—':status(date)}}</small></button><span v-else/></template></div><div class="calendar-legend"><span>● 완료</span><span>◐ 진행 중</span><span>— 미완료</span><span>휴식일</span></div></section><section class="day-records"><h2>{{Number(selected.slice(5,7))}}월 {{Number(selected.slice(-2))}}일</h2><p v-if="!records.length" class="empty-record"><AppIcon name="book" :size="34"/><span>{{status(selected)==='휴식일'?'쉬어가는 날이에요.':'아직 학습 기록이 없어요.'}}</span><small>학습하지 않은 날도 괜찮아요.</small></p><NuxtLink v-for="s in records" :key="s.id" :to="`/${s.status==='completed'?'result':'learn'}?id=${s.id}`" class="record-item"><span class="record-meta">{{s.type==='daily'?'매일 학습':'자유 학습'}}<small>{{s.status==='completed'?'완료':'진행 중'}}</small></span><b>{{s.attempts.length}} / {{s.questions.length}}문제 <AppIcon name="arrow" :size="17"/></b><p>정답률 {{summary(s).rate}}% · {{formatDuration(summary(s).duration)}}</p><small v-if="s.attempts.some(a=>!a.correct)">오답 복습 {{s.attempts.filter(a=>!a.correct&&reviewed(s,a.questionId)).length}} / {{summary(s).wrong}}</small></NuxtLink></section></div></div></template>
